import java.nio.charset.StandardCharsets;

class Person implements java.io.Serializable {
    String name; int age;
    Person(String n, int a) { name = n; age = a; }
}
public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        String[] p = input.split("\\s+");
        Person person = new Person(p[0], Integer.parseInt(p[1]));
        System.out.println("Person:" + person.name + ":" + person.age);
    }
}
